class candidatRepository extends \Doctrine\ORM\EntityRepository
{
    
    protected function persistAndFlush($entity)
    {
        $this->getEntityManager()->persist($entity);
        $this->getEntityManager()->flush();
        
    }
    
    protected function removeAndFlush($entity)
    {
        $this->getEntityManager()->remove($entity);
        $this->getEntityManager()->flush();
        
    }
    
    public function findAll()
    {
        return $this->findBy(array('etat' => 'Active'), array('prenom' => 'ASC'));
    }
    
    public function showAllCandidats()
    {
        $candidats = $this->findAll();
        
        $listeFinaleCandidats = array();
 
        foreach ($candidats as $candidat)
        {
            $photo = "bootstrap/img/profile.jpg";
            
            if(!empty($candidat->getPhoto()))
            {
                $photo = $candidat->getPhoto();
            }
            
            $anneeDemarrageCarriere = "N/A";
            
            if(!empty($candidat->getAnneeDemarrageCarriere()))
            {
                $anneeDemarrageCarriere = $candidat->getAnneeDemarrageCarriere();
            }
            
            $entreprise = "";
            
            if(!empty($candidat->getEntreprise()))
            {
                $entreprise = $candidat->getEntreprise()->getNom();
                $idEntreprise = $candidat->getEntreprise()->getId();
                $siteWebEntreprise = $candidat->getEntreprise()->getSiteWeb();
            }
            
            $listeCandidats = Array(
                'id' => $candidat->getId(),
                'prenom' => $candidat->getPrenom(),
                'nom' => $candidat->getNom(),
                'specialite' => $candidat->getSpecialite(),
                'telephone' => $candidat->getTelephone(),
                'anneeDemarrageCarriere' => $anneeDemarrageCarriere,
                'photo' => $photo,
                'visa' => $candidat->getVisa(),
                'etat' => $candidat->getEtat(),
                'entreprise' => $entreprise,
                'idEntreprise' => $idEntreprise,
                'siteWebEntreprise' => $siteWebEntreprise,
                'listeTechnologies' => $candidat->getListeTechnologies()
                );
            
            $listeFinaleCandidats[] = $listeCandidats;
        }
        return $listeFinaleCandidats;
        
    }
    
